import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int THREADS = 256;
__global__ void cute_matvec_kernel(
    const float* A,
    const float* B,
    float* C,
    int M,
    int K)
{
    constexpr int WARPS_PER_BLOCK = THREADS / 32;
    constexpr int ROWS_PER_WARP = 2;
    constexpr int TILE_K = 2048;
    __shared__ __align__(16) float smem_B[2][TILE_K];
    const int tid = static_cast<int>(threadIdx.x);
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int row_base =
        static_cast<int>(blockIdx.x) * WARPS_PER_BLOCK * ROWS_PER_WARP + warp;
    const int row0 = row_base;
    const int row1 = row_base + WARPS_PER_BLOCK;
    const bool active_row0 = row0 < M;
    const bool active_row1 = row1 < M;
    const bool vectorized =
        ((K & 3) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(A) & 15u) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(B) & 15u) == 0);
    float accum0 = 0.0f;
    float accum1 = 0.0f;
    if (vectorized) {
        int current = 0;
        const int first_size = min(TILE_K, K);
        const int first_vec_count = first_size >> 2;
        for (int i = tid; i < first_vec_count; i += THREADS) {
            const unsigned smem_addr = static_cast<unsigned>(
                __cvta_generic_to_shared(&smem_B[current][i * 4]));
            const float4* src = reinterpret_cast<const float4*>(B) + i;
            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                         :: "r"(smem_addr), "l"(src));
        }
        asm volatile("cp.async.commit_group;");
        asm volatile("cp.async.wait_group 0;");
        __syncthreads();
        for (int tile_base = 0; tile_base < K; tile_base += TILE_K) {
            const int tile_end = min(tile_base + TILE_K, K);
            const int tile_size = tile_end - tile_base;
            const int next_base = tile_base + TILE_K;
            const int next_buffer = current ^ 1;
            if (next_base < K) {
                const int next_size = min(TILE_K, K - next_base);
                const int next_vec_count = next_size >> 2;
                const float4* src =
                    reinterpret_cast<const float4*>(B + next_base);
                for (int i = tid; i < next_vec_count; i += THREADS) {
                    const unsigned smem_addr = static_cast<unsigned>(
                        __cvta_generic_to_shared(&smem_B[next_buffer][i * 4]));
                    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;"
                                 :: "r"(smem_addr), "l"(src + i));
                }
                asm volatile("cp.async.commit_group;");
            }
            const float4* b_vec =
                reinterpret_cast<const float4*>(smem_B[current]);
            const int vec_count = tile_size >> 2;
            if (active_row0) {
                const float* row_a0 = A + static_cast<std::size_t>(row0) * K;
                const float4* a_vec0 =
                    reinterpret_cast<const float4*>(row_a0 + tile_base);
                for (int i = lane; i < vec_count; i += 32) {
                    const float4 av = a_vec0[i];
                    const float4 bv = b_vec[i];
                    accum0 = fmaf(av.x, bv.x, accum0);
                    accum0 = fmaf(av.y, bv.y, accum0);
                    accum0 = fmaf(av.z, bv.z, accum0);
                    accum0 = fmaf(av.w, bv.w, accum0);
                }
            }
            if (active_row1) {
                const float* row_a1 = A + static_cast<std::size_t>(row1) * K;
                const float4* a_vec1 =
                    reinterpret_cast<const float4*>(row_a1 + tile_base);
                for (int i = lane; i < vec_count; i += 32) {
                    const float4 av = a_vec1[i];
                    const float4 bv = b_vec[i];
                    accum1 = fmaf(av.x, bv.x, accum1);
                    accum1 = fmaf(av.y, bv.y, accum1);
                    accum1 = fmaf(av.z, bv.z, accum1);
                    accum1 = fmaf(av.w, bv.w, accum1);
                }
            }
            asm volatile("cp.async.wait_group 0;");
            __syncthreads();
            current = next_buffer;
        }
    } else {
        for (int tile_base = 0; tile_base < K; tile_base += TILE_K) {
            const int tile_end = min(tile_base + TILE_K, K);
            const int tile_size = tile_end - tile_base;
            for (int k = tid; k < tile_size; k += THREADS)
                smem_B[0][k] = B[tile_base + k];
            __syncthreads();
            if (active_row0) {
                const float* row_a0 = A + static_cast<std::size_t>(row0) * K;
                for (int k = lane; k < tile_size; k += 32)
                    accum0 = fmaf(row_a0[tile_base + k], smem_B[0][k], accum0);
            }
            if (active_row1) {
                const float* row_a1 = A + static_cast<std::size_t>(row1) * K;
                for (int k = lane; k < tile_size; k += 32)
                    accum1 = fmaf(row_a1[tile_base + k], smem_B[0][k], accum1);
            }
            __syncthreads();
        }
    }
    if (active_row0) {
        for (int offset = 16; offset > 0; offset >>= 1)
            accum0 += __shfl_down_sync(0xFFFFFFFFu, accum0, offset);
        if (lane == 0) C[row0] = accum0;
    }
    if (active_row1) {
        for (int offset = 16; offset > 0; offset >>= 1)
            accum1 += __shfl_down_sync(0xFFFFFFFFu, accum1, offset);
        if (lane == 0) C[row1] = accum1;
    }
}


torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must have shape (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must have shape (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));

    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");

    auto C = torch::empty({M, 1}, A.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matvec_kernel<<<
        dim3((M + (THREADS / 32) * 2 - 1) / ((THREADS / 32) * 2)),
        dim3(THREADS),
        2048 * sizeof(float),
        stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix-vector kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)

